// DIAGNÓSTICO — não grava nada, só descreve o que a API devolveu.
// Ligar depois do node "Ler planilha" e olhar a saída.

const resp = $input.first().json;
const rowData = resp?.sheets?.[0]?.data?.[0]?.rowData || [];

const linkDe = (v) => ({
  hyperlink: v?.hyperlink || '',
  cellFormat: v?.userEnteredFormat?.textFormat?.link?.uri || '',
  textRun: (v?.textFormatRuns || []).map((r) => r?.format?.link?.uri).find(Boolean) || '',
});

// 1) cabeçalho: índice + letra + título de cada coluna
const letra = (i) => String.fromCharCode(65 + i);
const cabecalho = (rowData[0]?.values || []).map((v, i) => ({
  i,
  col: letra(i),
  titulo: v?.formattedValue || '',
})).filter((c) => c.titulo);

// 2) onde existe link, em qualquer célula da planilha inteira
const linksPorColuna = {};
let totalComLink = 0;
rowData.forEach((row) => {
  (row?.values || []).forEach((v, i) => {
    const l = linkDe(v);
    const achou = l.hyperlink || l.cellFormat || l.textRun;
    if (!achou) return;
    totalComLink++;
    const k = letra(i);
    linksPorColuna[k] = linksPorColuna[k] || { total: 0, via: {}, exemplo: '' };
    linksPorColuna[k].total++;
    const via = l.hyperlink ? 'hyperlink' : (l.cellFormat ? 'cellFormat' : 'textRun');
    linksPorColuna[k].via[via] = (linksPorColuna[k].via[via] || 0) + 1;
    if (!linksPorColuna[k].exemplo) linksPorColuna[k].exemplo = achou.slice(0, 90);
  });
});

// 3) as 3 primeiras linhas de dados, célula a célula
const amostra = [];
for (let i = 1; i < Math.min(rowData.length, 4); i++) {
  const cels = (rowData[i]?.values || []).map((v, j) => {
    const l = linkDe(v);
    const link = l.hyperlink || l.cellFormat || l.textRun;
    const valor = v?.formattedValue || '';
    if (!valor && !link) return null;
    return { col: letra(j), valor: valor.slice(0, 45), link: link ? link.slice(0, 70) : '' };
  }).filter(Boolean);
  amostra.push({ linha: i + 1, cels });
}

// 4) quantos nomes casam com o filtro atual
const COL_NOME = 1; // B
const nomesColB = rowData.slice(1)
  .map((r) => (r?.values?.[COL_NOME]?.formattedValue || '').trim())
  .filter(Boolean);

return [{ json: {
  totalLinhas: rowData.length,
  cabecalho,
  linksPorColuna,
  totalCelulasComLink: totalComLink,
  colunaB: {
    preenchidas: nomesColB.length,
    casamComSeal_ad: nomesColB.filter((n) => /^seal_ad/i.test(n)).length,
    primeiros5: nomesColB.slice(0, 5),
  },
  amostra,
} }];
